Since the CREATE VIEW statement can be
executed as a prepared statement, it is possible to dynamically create the
view that is queried by the cursor. From MariaDB 10.3.0, cursors can have parameters. Cursor parameters can appear
in any part of the DECLARE CURSOR select_statement where a stored procedure
variable is allowed (select list, WHERE, HAVING, LIMIT etc). See DECLARE
CURSOR and OPEN for syntax, and below for an example: Examples
-------- CREATE TABLE c1(i INT); CREATE TABLE c2(i INT); CREATE TABLE c3(i INT); DELIMITER // CREATE PROCEDURE p1()
BEGIN
DECLARE done INT DEFAULT FALSE;
DECLARE x, y INT;
DECLARE cur1 CURSOR FOR SELECT i FROM test.c1;
DECLARE cur2 CURSOR FOR SELECT i FROM test.c2;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE; OPEN cur1;
OPEN cur2; read_loop: LOOP
FETCH cur1 INTO x;
FETCH cur2 INTO y;
IF done THEN
LEAVE read_loop;
END IF;
IF x < y THEN
INSERT INTO test.c3 VALUES (x);
ELSE
INSERT INTO test.c3 VALUES (y);
END IF;
END LOOP; CLOSE cur1;
CLOSE cur2;
END; // DELIMITER ; INSERT INTO c1 VALUES(5),(50),(500); INSERT INTO c2 VALUES(10),(20),(30); CALL p1; SELECT * FROM c3;
